<!-- @generated by qw-codegen (crud) -->
<template>
  <view class="qw-detail qw-stack">
    <view v-if="ready" class="qw-form">
      <view class="qw-field">
        <text class="qw-field__label is-required">{{ t('field.demo.book.isbn') }}</text>
        <wd-input v-model="form.isbn" :maxlength="20" clearable />
        <text v-if="errors.isbn" class="qw-field__error">{{ errors.isbn }}</text>
      </view>
      <view class="qw-field">
        <text class="qw-field__label is-required">{{ t('field.demo.book.title') }}</text>
        <wd-input v-model="form.title" :maxlength="200" clearable />
        <text v-if="errors.title" class="qw-field__error">{{ errors.title }}</text>
      </view>
      <view class="qw-field">
        <text class="qw-field__label">{{ t('field.demo.book.author') }}</text>
        <wd-input v-model="form.author" :maxlength="100" clearable />
        <text v-if="errors.author" class="qw-field__error">{{ errors.author }}</text>
      </view>
      <view class="qw-field">
        <text class="qw-field__label">{{ t('field.demo.book.coverUrl') }}</text>
        <QwUpload
          :model-value="uploadsOf(form.coverUrl, 'image')"
          biz-tag="cover"
          :limit="1"
          @update:model-value="form.coverUrl = uploadText($event, 'image')"
        />
        <text v-if="errors.coverUrl" class="qw-field__error">{{ errors.coverUrl }}</text>
      </view>
      <view class="qw-field">
        <wd-cell
          :title="t('field.demo.book.publishedOn')"
          :value="form.publishedOn ?? ''"
          :placeholder="t('picker.select')"
          is-link
          @click="pickDate(form, 'publishedOn', 'date', t('field.demo.book.publishedOn'))"
        />
        <text v-if="errors.publishedOn" class="qw-field__error">{{ errors.publishedOn }}</text>
      </view>
      <view class="qw-field">
        <text class="qw-field__label">{{ t('field.demo.book.price') }}</text>
        <wd-input-number
          :model-value="form.price ?? ''"
          :min="-99999999.99"
          :max="99999999.99"
          :precision="2"
          :step="0.01"
          allow-null
          @update:model-value="form.price = numOf($event)"
        />
        <text v-if="errors.price" class="qw-field__error">{{ errors.price }}</text>
      </view>
      <view class="qw-field">
        <QwDictSelect
          v-model="form.genre"
          code="demo.genre"
          :label="t('field.demo.book.genre')"
          required
        />
        <text v-if="errors.genre" class="qw-field__error">{{ errors.genre }}</text>
      </view>
      <view class="qw-field">
        <QwDeptPicker v-model="form.deptId" :label="t('field.demo.book.deptId')" />
        <text v-if="errors.deptId" class="qw-field__error">{{ errors.deptId }}</text>
      </view>
      <view class="qw-field">
        <wd-cell :title="t('field.demo.book.enabled')" center>
          <wd-switch v-model="form.enabled" />
        </wd-cell>
        <text v-if="errors.enabled" class="qw-field__error">{{ errors.enabled }}</text>
      </view>
      <text v-if="error" class="qw-form__error" role="alert">{{ error }}</text>
      <wd-button
        custom-class="qw-btn qw-btn--primary"
        type="primary"
        block
        :loading="submitting"
        :disabled="submitting"
        @click="submit"
      >
        {{ t('crud.action.save') }}
      </wd-button>
    </view>
    <QwEmpty v-else-if="error" :title="error" />
    <!-- one picker for every date field (of a row too) -->
    <wd-datetime-picker
      :model-value="pickedAt"
      :visible="!!picking"
      :type="picking?.type ?? 'date'"
      :title="picking?.title ?? ''"
      root-portal
      @confirm="pick"
      @update:visible="closed"
    />
  </view>
</template>

<script setup lang="ts">
import { computed, reactive, ref, shallowRef, watch } from 'vue'
import { onLoad } from '@dcloudio/uni-app'
import {
  type BookCreate,
  bookCreate,
  uploadsOf,
  uploadText,
  type ValidationIssue,
} from '@qiwu/shared'
import { bookApi } from '@/api/demo/book'
import QwDeptPicker from '@/core/components/QwDeptPicker.vue'
import QwDictSelect from '@/core/components/QwDictSelect.vue'
import QwEmpty from '@/core/components/QwEmpty.vue'
import QwUpload from '@/core/components/QwUpload.vue'
import { fillForm, type Form, numOf, useDatePicker } from '@/core/crud'
import { fieldErrors, t } from '@/core/i18n'
import { ApiError, errorText } from '@/core/request'

/**
 * Add / edit page of the book list (mobile, generated): `?id=` edits that row, else it
 * adds one. The rules: the shared `bookCreate`
 * (the server checks again). The save button shows loading and is disabled while pending.
 */
const id = ref(0)
const ready = ref(false)
const error = ref('')
const submitting = ref(false)
const form = reactive<Form<BookCreate>>({
  isbn: '',
  title: '',
  author: '',
  coverUrl: '',
  publishedOn: null,
  price: 0,
  genre: '',
  deptId: null,
  enabled: true,
})
const issues = shallowRef<ValidationIssue[]>([])
const errors = computed(() => fieldErrors(bookCreate, issues.value))
// once shown, the messages follow the input
watch(form, () => {
  if (issues.value.length) issues.value = bookCreate.safeParse(form).error?.issues ?? []
})
const { picking, value: pickedAt, open: pickDate, pick, closed } = useDatePicker()

onLoad(async (query) => {
  id.value = Number(query?.id) || 0
  const name = t('demo.book.entity')
  uni.setNavigationBarTitle({
    title: t(id.value ? 'crud.title.edit' : 'crud.title.create', { name }),
  })
  if (id.value)
    try {
      fillForm(form, await bookApi.get(id.value))
    } catch (e) {
      return void (error.value = errorText(e))
    }
  ready.value = true
})

async function submit() {
  if (submitting.value) return
  const parsed = bookCreate.safeParse(form)
  issues.value = parsed.error?.issues ?? []
  if (!parsed.success) return
  submitting.value = true
  error.value = ''
  try {
    if (id.value) await bookApi.update(id.value, parsed.data)
    else await bookApi.create(parsed.data)
    uni.showToast({ title: t(id.value ? 'crud.msg.updated' : 'crud.msg.created'), icon: 'none' })
    uni.navigateBack()
  } catch (e) {
    // a 400 (the rules), a 404 (gone, out of scope) belongs here; the request layer toasts the rest (409: a
    // unique value taken)
    if (e instanceof ApiError && (e.status === 400 || e.status === 404)) error.value = e.message
  } finally {
    submitting.value = false
  }
}
</script>
